-- Ecuador story arc: 3 stories, spanning the November 2022 "goes
-- universal" milestone, the November 2024 electrical-emergency
-- relaxation, and a current-development story framed close to today's
-- date (2026-08-05) covering the January 2026 real-time-transmission
-- closure and June 2026's Executive Decree 398. Matches the
-- richer-country pattern (Argentina, Colombia, Indonesia) rather than a
-- single launch post. Live-researched via direct reads of SRI's own
-- resolution PDFs (sri.gob.ec) plus Primicias, El Comercio, AVL
-- Abogados, Sovos, and EDICOM.
--
-- CRITICAL FRAMING: story 3 explicitly frames the January 2026 change as
-- closing a temporary emergency relaxation, not introducing real-time
-- reporting for the first time -- see its html body below.

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2022-11-30-ecuador-universal-coverage', '2022-11-30', '2022-11', 'By late November 2022, Ecuador''s SRI had authorized 1,212,712 taxpayers for electronic invoicing, following waves of sector- and threshold-based mandatory rollout -- effectively universal coverage, with one real carve-out remaining for RIMPE ''Negocios Populares'' taxpayers.', '<h3>🇪🇨 Ecuador''s e-invoicing mandate reaches effectively universal coverage</h3>
<p>By 29-30 November 2022, Ecuador''s Servicio de Rentas Internas (SRI) had authorized 1,212,712 taxpayers for electronic invoicing, the culmination of a phased rollout that had been underway since Resolution NAC-DGERCGC14-00790 first made real-time invoice validation binding for designated taxpayer groups back in 2014. The path there ran through several distinct waves: heavy machinery and LPG distributors brought into scope in 2020, B2G supplies over $1,000 mandated in 2021, the new simplified RIMPE tax regime created 1 January 2022, and the $200,000-$300,000 income bracket added later that year.</p>
<p>The result is coverage that is effectively universal across Ecuador''s VAT-registered business population -- but not literally total. One real carve-out remains: taxpayers under RIMPE''s ''Negocios Populares'' category (annual income up to $20,000) are exempt from the electronic-invoicing mandate and may continue using paper ''notas de venta RISE''. Only RIMPE ''Emprendedores'' (income up to $300,000) and larger taxpayers are actually obligated to issue electronic invoices.</p>
<p>For businesses trading with Ecuadorian counterparties, the practical takeaway is nuanced: assume your trading partner is on electronic invoicing unless you have specific reason to think they fall into the smallest RIMPE tier.</p>', 'https://www.sri.gob.ec/facturacion-electronica', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2022-11-30-ecuador-universal-coverage', id FROM countries WHERE name_en = 'Ecuador';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2022-11-30-ecuador-universal-coverage', 'en', 'Ecuador''s e-invoicing mandate reaches effectively universal coverage', 'By late November 2022, Ecuador''s SRI had authorized 1,212,712 taxpayers for electronic invoicing, following waves of sector- and threshold-based mandatory rollout -- effectively universal coverage, with one real carve-out remaining for RIMPE ''Negocios Populares'' taxpayers.', '<h3>🇪🇨 Ecuador''s e-invoicing mandate reaches effectively universal coverage</h3>
<p>By 29-30 November 2022, Ecuador''s Servicio de Rentas Internas (SRI) had authorized 1,212,712 taxpayers for electronic invoicing, the culmination of a phased rollout that had been underway since Resolution NAC-DGERCGC14-00790 first made real-time invoice validation binding for designated taxpayer groups back in 2014. The path there ran through several distinct waves: heavy machinery and LPG distributors brought into scope in 2020, B2G supplies over $1,000 mandated in 2021, the new simplified RIMPE tax regime created 1 January 2022, and the $200,000-$300,000 income bracket added later that year.</p>
<p>The result is coverage that is effectively universal across Ecuador''s VAT-registered business population -- but not literally total. One real carve-out remains: taxpayers under RIMPE''s ''Negocios Populares'' category (annual income up to $20,000) are exempt from the electronic-invoicing mandate and may continue using paper ''notas de venta RISE''. Only RIMPE ''Emprendedores'' (income up to $300,000) and larger taxpayers are actually obligated to issue electronic invoices.</p>
<p>For businesses trading with Ecuadorian counterparties, the practical takeaway is nuanced: assume your trading partner is on electronic invoicing unless you have specific reason to think they fall into the smallest RIMPE tier.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2022-11-30-ecuador-universal-coverage', 'es', 'El mandato de facturación electrónica de Ecuador alcanza una cobertura prácticamente universal', 'A finales de noviembre de 2022, el SRI de Ecuador había autorizado a 1.212.712 contribuyentes para la facturación electrónica, tras varias oleadas de despliegue obligatorio por sector y umbral -- una cobertura prácticamente universal, con una excepción real todavía vigente para los contribuyentes RIMPE ''Negocios Populares''.', '<h3>🇪🇨 El mandato de facturación electrónica de Ecuador alcanza una cobertura prácticamente universal</h3>
<p>Al 29-30 de noviembre de 2022, el Servicio de Rentas Internas (SRI) de Ecuador había autorizado a 1.212.712 contribuyentes para la facturación electrónica, la culminación de un despliegue escalonado en marcha desde que la Resolución NAC-DGERCGC14-00790 hizo vinculante por primera vez la validación de facturas en tiempo real para grupos designados de contribuyentes allá por 2014. El camino hasta ahí pasó por varias oleadas diferenciadas: maquinaria pesada y distribuidores de GLP incorporados en 2020, suministros B2G superiores a 1.000 USD obligados en 2021, el nuevo régimen tributario simplificado RIMPE creado el 1 de enero de 2022, y el tramo de ingresos de 200.000-300.000 USD añadido más adelante ese mismo año.</p>
<p>El resultado es una cobertura prácticamente universal entre la población empresarial ecuatoriana registrada a efectos de IVA -- pero no literalmente total. Queda una excepción real: los contribuyentes de la categoría RIMPE ''Negocios Populares'' (ingresos anuales de hasta 20.000 USD) están exentos del mandato de facturación electrónica y pueden seguir utilizando ''notas de venta RISE'' en papel. Solo los RIMPE ''Emprendedores'' (ingresos de hasta 300.000 USD) y los contribuyentes de mayor tamaño están realmente obligados a emitir facturas electrónicas.</p>
<p>Para las empresas que comercian con contrapartes ecuatorianas, la conclusión práctica es matizada: asuma que su socio comercial está en facturación electrónica, salvo que tenga motivos concretos para pensar que se encuentra en el nivel más pequeño de RIMPE.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2022-11-30-ecuador-universal-coverage', 'de', 'Ecuadors E-Rechnungspflicht erreicht praktisch flächendeckende Abdeckung', 'Bis Ende November 2022 hatte Ecuadors SRI 1.212.712 Steuerpflichtige für die elektronische Rechnungsstellung freigegeben, nach mehreren Wellen sektor- und schwellenwertbasierter Pflichteinführung -- eine praktisch flächendeckende Abdeckung, mit einer verbleibenden echten Ausnahme für RIMPE-„Negocios Populares"-Steuerpflichtige.', '<h3>🇪🇨 Ecuadors E-Rechnungspflicht erreicht praktisch flächendeckende Abdeckung</h3>
<p>Bis zum 29./30. November 2022 hatte der Servicio de Rentas Internas (SRI) Ecuadors 1.212.712 Steuerpflichtige für die elektronische Rechnungsstellung freigegeben -- der Höhepunkt einer stufenweisen Einführung, die seit der Entschließung NAC-DGERCGC14-00790, die 2014 die Echtzeitvalidierung von Rechnungen erstmals für designierte Steuerpflichtigengruppen verbindlich machte, im Gange war. Der Weg dorthin führte über mehrere einzelne Wellen: Schwermaschinen und LPG-Vertreiber 2020 einbezogen, B2G-Lieferungen über 1.000 USD 2021 verpflichtend, das neue vereinfachte RIMPE-Steuerregime am 1. Januar 2022 geschaffen, und die Einkommensklasse 200.000-300.000 USD später im selben Jahr hinzugefügt.</p>
<p>Das Ergebnis ist eine praktisch flächendeckende Abdeckung der umsatzsteuerlich registrierten ecuadorianischen Unternehmen -- aber nicht buchstäblich vollständig. Eine echte Ausnahme bleibt bestehen: Steuerpflichtige der RIMPE-Kategorie „Negocios Populares" (Jahreseinkommen bis 20.000 USD) sind von der E-Rechnungspflicht befreit und dürfen weiterhin Papier-„notas de venta RISE" verwenden. Nur RIMPE „Emprendedores" (Einkommen bis 300.000 USD) und größere Steuerpflichtige sind tatsächlich zur Ausstellung elektronischer Rechnungen verpflichtet.</p>
<p>Für Unternehmen, die mit ecuadorianischen Gegenparteien handeln, lautet die praktische Schlussfolgerung differenziert: Gehen Sie davon aus, dass Ihr Handelspartner elektronisch abrechnet, es sei denn, Sie haben konkrete Gründe zur Annahme, dass er in die kleinste RIMPE-Stufe fällt.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2022-11-30-ecuador-universal-coverage', 'fr', 'L''obligation de facturation électronique de l''Équateur atteint une couverture pratiquement universelle', 'Fin novembre 2022, le SRI équatorien avait autorisé 1 212 712 contribuables pour la facturation électronique, à la suite de plusieurs vagues de déploiement obligatoire par secteur et par seuil -- une couverture pratiquement universelle, avec une véritable exception subsistant pour les contribuables RIMPE « Negocios Populares ».', '<h3>🇪🇨 L''obligation de facturation électronique de l''Équateur atteint une couverture pratiquement universelle</h3>
<p>Au 29-30 novembre 2022, le Servicio de Rentas Internas (SRI) équatorien avait autorisé 1 212 712 contribuables pour la facturation électronique, aboutissement d''un déploiement progressif en cours depuis que la résolution NAC-DGERCGC14-00790 avait rendu contraignante pour la première fois, en 2014, la validation des factures en temps réel pour des groupes de contribuables désignés. Le chemin parcouru est passé par plusieurs vagues distinctes : machines lourdes et distributeurs de GPL intégrés en 2020, fournitures B2G supérieures à 1 000 USD rendues obligatoires en 2021, le nouveau régime fiscal simplifié RIMPE créé le 1er janvier 2022, et la tranche de revenus de 200 000 à 300 000 USD ajoutée plus tard cette même année.</p>
<p>Le résultat est une couverture pratiquement universelle au sein de la population d''entreprises équatoriennes assujetties à la TVA -- mais pas littéralement totale. Une véritable exception subsiste : les contribuables de la catégorie RIMPE « Negocios Populares » (revenus annuels jusqu''à 20 000 USD) sont exemptés de l''obligation de facturation électronique et peuvent continuer à utiliser des « notas de venta RISE » papier. Seuls les RIMPE « Emprendedores » (revenus jusqu''à 300 000 USD) et les contribuables plus importants sont réellement tenus d''émettre des factures électroniques.</p>
<p>Pour les entreprises commerçant avec des contreparties équatoriennes, la conclusion pratique est nuancée : présumez que votre partenaire commercial pratique la facturation électronique, sauf si vous avez une raison précise de penser qu''il relève du plus petit palier RIMPE.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2024-11-05-ecuador-emergency-relaxation', '2024-11-05', '2024-11', 'Amid a national electrical emergency and rolling blackouts, Ecuador''s SRI granted businesses a temporary 4-business-day window to transmit electronic invoices -- a genuine, time-limited relief measure, not a rollback of the underlying mandate.', '<h3>🇪🇨 Amid blackouts, SRI gives Ecuadorian businesses breathing room on invoice transmission</h3>
<p>2024 was a hard year for Ecuador''s electricity grid. A severe drought hit hydroelectric generation -- the backbone of the country''s power supply -- triggering a national electrical emergency and rolling blackouts that at points stretched to many hours a day, disrupting businesses nationwide, invoicing systems very much included.</p>
<p>On 5 November 2024, SRI responded with Resolution NAC-DGERCGC24-00000035, relaxing the standing rule that electronic invoices be transmitted for validation immediately, at the moment of the transaction. Under the new resolution, businesses could transmit within a maximum of 4 business days of generating a document instead -- a real, practical concession for businesses whose systems, connectivity, or staff availability were being disrupted by the power crisis.</p>
<p>It''s worth being precise about what this was and wasn''t: a temporary, crisis-specific relief measure responding to genuinely exceptional circumstances, not a permanent loosening of Ecuador''s e-invoicing mandate or a sign the underlying near-real-time requirement -- in place since 2014 -- was being abandoned. As the electrical emergency eased, so did the relief: the window was closed just over a year later, from 1 January 2026.</p>', 'https://www.sri.gob.ec/o/sri-portlet-biblioteca-alfresco-internet/descargar?id=NAC-DGERCGC24-00000035', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2024-11-05-ecuador-emergency-relaxation', id FROM countries WHERE name_en = 'Ecuador';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-11-05-ecuador-emergency-relaxation', 'en', 'Amid blackouts, SRI gives Ecuadorian businesses breathing room on invoice transmission', 'Amid a national electrical emergency and rolling blackouts, Ecuador''s SRI granted businesses a temporary 4-business-day window to transmit electronic invoices -- a genuine, time-limited relief measure, not a rollback of the underlying mandate.', '<h3>🇪🇨 Amid blackouts, SRI gives Ecuadorian businesses breathing room on invoice transmission</h3>
<p>2024 was a hard year for Ecuador''s electricity grid. A severe drought hit hydroelectric generation -- the backbone of the country''s power supply -- triggering a national electrical emergency and rolling blackouts that at points stretched to many hours a day, disrupting businesses nationwide, invoicing systems very much included.</p>
<p>On 5 November 2024, SRI responded with Resolution NAC-DGERCGC24-00000035, relaxing the standing rule that electronic invoices be transmitted for validation immediately, at the moment of the transaction. Under the new resolution, businesses could transmit within a maximum of 4 business days of generating a document instead -- a real, practical concession for businesses whose systems, connectivity, or staff availability were being disrupted by the power crisis.</p>
<p>It''s worth being precise about what this was and wasn''t: a temporary, crisis-specific relief measure responding to genuinely exceptional circumstances, not a permanent loosening of Ecuador''s e-invoicing mandate or a sign the underlying near-real-time requirement -- in place since 2014 -- was being abandoned. As the electrical emergency eased, so did the relief: the window was closed just over a year later, from 1 January 2026.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-11-05-ecuador-emergency-relaxation', 'es', 'En medio de los apagones, el SRI da un respiro a las empresas ecuatorianas en la transmisión de facturas', 'En medio de una emergencia eléctrica nacional y apagones rotativos, el SRI de Ecuador concedió a las empresas una ventana temporal de 4 días hábiles para transmitir facturas electrónicas -- una medida de alivio real y limitada en el tiempo, no un retroceso del mandato subyacente.', '<h3>🇪🇨 En medio de los apagones, el SRI da un respiro a las empresas ecuatorianas en la transmisión de facturas</h3>
<p>2024 fue un año duro para la red eléctrica de Ecuador. Una sequía severa golpeó la generación hidroeléctrica -- la columna vertebral del suministro eléctrico del país -- desencadenando una emergencia eléctrica nacional y apagones rotativos que en algunos momentos se extendieron durante muchas horas al día, alterando a las empresas en todo el país, y muy en particular a los sistemas de facturación.</p>
<p>El 5 de noviembre de 2024, el SRI respondió con la Resolución NAC-DGERCGC24-00000035, que flexibilizó la regla vigente de que las facturas electrónicas debían transmitirse para su validación de forma inmediata, en el momento de la transacción. Con la nueva resolución, las empresas pudieron transmitir en un plazo máximo de 4 días hábiles desde la generación de un documento -- una concesión real y práctica para las empresas cuyos sistemas, conectividad o disponibilidad de personal se veían alterados por la crisis energética.</p>
<p>Conviene ser precisos sobre qué fue esto y qué no fue: una medida de alivio temporal y específica de la crisis, en respuesta a circunstancias genuinamente excepcionales, no una flexibilización permanente del mandato de facturación electrónica de Ecuador ni una señal de que se estuviera abandonando el requisito subyacente casi en tiempo real -- vigente desde 2014. A medida que la emergencia eléctrica se fue superando, también lo hizo el alivio: la ventana se cerró poco más de un año después, a partir del 1 de enero de 2026.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-11-05-ecuador-emergency-relaxation', 'de', 'Inmitten von Stromausfällen verschafft das SRI ecuadorianischen Unternehmen bei der Rechnungsübermittlung Luft', 'Inmitten eines nationalen Stromnotstands und rollierender Stromausfälle gewährte Ecuadors SRI Unternehmen ein vorübergehendes Fenster von 4 Werktagen zur Übermittlung elektronischer Rechnungen -- eine echte, zeitlich begrenzte Entlastungsmaßnahme, keine Rücknahme der zugrunde liegenden Pflicht.', '<h3>🇪🇨 Inmitten von Stromausfällen verschafft das SRI ecuadorianischen Unternehmen bei der Rechnungsübermittlung Luft</h3>
<p>2024 war ein hartes Jahr für Ecuadors Stromnetz. Eine schwere Dürre traf die Wasserkrafterzeugung -- das Rückgrat der Stromversorgung des Landes -- und löste einen nationalen Stromnotstand sowie rollierende Stromausfälle aus, die zeitweise viele Stunden am Tag dauerten und Unternehmen landesweit störten, Rechnungssysteme eingeschlossen.</p>
<p>Am 5. November 2024 reagierte das SRI mit der Entschließung NAC-DGERCGC24-00000035 und lockerte die geltende Regel, wonach elektronische Rechnungen sofort, im Moment der Transaktion, zur Validierung übermittelt werden mussten. Nach der neuen Entschließung konnten Unternehmen stattdessen innerhalb von höchstens 4 Werktagen nach Erstellung eines Dokuments übermitteln -- ein echtes, praktisches Zugeständnis für Unternehmen, deren Systeme, Konnektivität oder Personalverfügbarkeit durch die Energiekrise beeinträchtigt waren.</p>
<p>Es lohnt sich, genau zu sein, was dies war und was nicht: eine vorübergehende, krisenspezifische Entlastungsmaßnahme als Reaktion auf echte Ausnahmeumstände, keine dauerhafte Lockerung von Ecuadors E-Rechnungspflicht und kein Zeichen dafür, dass die seit 2014 geltende Echtzeit-nahe Anforderung aufgegeben würde. Mit dem Abklingen des Stromnotstands endete auch die Entlastung: Das Fenster wurde etwas mehr als ein Jahr später, ab dem 1. Januar 2026, wieder geschlossen.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-11-05-ecuador-emergency-relaxation', 'fr', 'En pleine crise des coupures de courant, le SRI accorde un répit aux entreprises équatoriennes sur la transmission des factures', 'En pleine urgence électrique nationale et coupures de courant tournantes, le SRI équatorien a accordé aux entreprises un délai temporaire de 4 jours ouvrables pour transmettre les factures électroniques -- une véritable mesure d''allègement limitée dans le temps, et non un recul de l''obligation sous-jacente.', '<h3>🇪🇨 En pleine crise des coupures de courant, le SRI accorde un répit aux entreprises équatoriennes sur la transmission des factures</h3>
<p>2024 a été une année difficile pour le réseau électrique de l''Équateur. Une sécheresse sévère a frappé la production hydroélectrique -- l''épine dorsale de l''approvisionnement électrique du pays -- déclenchant une urgence électrique nationale et des coupures de courant tournantes qui ont par moments duré de nombreuses heures par jour, perturbant les entreprises dans tout le pays, systèmes de facturation compris.</p>
<p>Le 5 novembre 2024, le SRI a réagi avec la résolution NAC-DGERCGC24-00000035, assouplissant la règle en vigueur selon laquelle les factures électroniques devaient être transmises pour validation immédiatement, au moment de la transaction. En vertu de la nouvelle résolution, les entreprises pouvaient désormais transmettre dans un délai maximal de 4 jours ouvrables suivant la génération d''un document -- une concession réelle et pratique pour les entreprises dont les systèmes, la connectivité ou la disponibilité du personnel étaient perturbés par la crise énergétique.</p>
<p>Il convient d''être précis sur ce que cela était et n''était pas : une mesure d''allègement temporaire et propre à la crise, répondant à des circonstances véritablement exceptionnelles, et non un assouplissement permanent de l''obligation de facturation électronique de l''Équateur, ni un signe que l''exigence de quasi-temps réel en vigueur depuis 2014 était abandonnée. À mesure que l''urgence électrique s''est résorbée, l''allègement a lui aussi pris fin : le délai a été supprimé un peu plus d''un an plus tard, à compter du 1er janvier 2026.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-08-05-ecuador-realtime-closure-and-decree398', '2026-08-05', '2026-08', 'Ecuador closed its temporary electrical-emergency invoicing relaxation on 1 January 2026, restoring the immediate-transmission rule that has applied since 2014 -- and in June 2026, Executive Decree 398 built on that continuous data stream to modernize goods and services traceability.', '<h3>🇪🇨 Ecuador closes its emergency-era invoicing relaxation, then builds on the data stream it restored</h3>
<p>It''s worth being precise about what changed in Ecuador''s e-invoicing regime on 1 January 2026 -- because it''s easy to mischaracterize. This was not the introduction of real-time invoice reporting. Ecuador''s SRI has required near-real-time transmission since Resolution NAC-DGERCGC14-00790 in 2014, tightened and loosened at the margins several times since, most recently by the 72-hour high-volume allowance added in 2018. What actually happened on 1 January 2026 is that the temporary 4-business-day grace period granted in November 2024, during Ecuador''s national electrical-emergency and blackout crisis, was eliminated -- reverting the country to its standing immediate-transmission baseline.</p>
<p>The change had a winding path to its effective date. Resolution NAC-DGERCGC25-00000014 (27 June 2025) deleted the ''or up to a maximum of four business days'' clause from Article 7, originally set to take effect 1 August 2025. But Resolution NAC-DGERCGC25-00000017 (29-30 July 2025) deferred that effective date to 1 January 2026, giving businesses roughly five extra months to adjust, while also shortening the invoice-cancellation window deadline from the 10th to the 7th of the following month and making ''consumidor final'' invoices non-cancellable outright.</p>
<p>Then, on 3 June 2026, the government issued Executive Decree 398, modernizing traceability and authentication mechanisms for goods and certain services. Press coverage from El Comercio frames the decree explicitly as building on the continuous, real-time invoice data stream SRI now receives -- since immediate transmission was restored -- to enable ongoing tax monitoring rather than the older model of reviewing data only after periodic declarations were filed. Read together, the two developments tell a coherent story: a mature, decade-old real-time invoicing infrastructure, briefly relaxed for a genuine crisis, restored, and now being actively built upon.</p>', 'https://www.sri.gob.ec/o/sri-portlet-biblioteca-alfresco-internet/descargar?id=e98fc8a6-299e-4ea9-8de7-2f6c70dbb4f5&nombre=NAC-DGERCGC25-00000017.pdf', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-08-05-ecuador-realtime-closure-and-decree398', id FROM countries WHERE name_en = 'Ecuador';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-08-05-ecuador-realtime-closure-and-decree398', 'en', 'Ecuador closes its emergency-era invoicing relaxation, then builds on the data stream it restored', 'Ecuador closed its temporary electrical-emergency invoicing relaxation on 1 January 2026, restoring the immediate-transmission rule that has applied since 2014 -- and in June 2026, Executive Decree 398 built on that continuous data stream to modernize goods and services traceability.', '<h3>🇪🇨 Ecuador closes its emergency-era invoicing relaxation, then builds on the data stream it restored</h3>
<p>It''s worth being precise about what changed in Ecuador''s e-invoicing regime on 1 January 2026 -- because it''s easy to mischaracterize. This was not the introduction of real-time invoice reporting. Ecuador''s SRI has required near-real-time transmission since Resolution NAC-DGERCGC14-00790 in 2014, tightened and loosened at the margins several times since, most recently by the 72-hour high-volume allowance added in 2018. What actually happened on 1 January 2026 is that the temporary 4-business-day grace period granted in November 2024, during Ecuador''s national electrical-emergency and blackout crisis, was eliminated -- reverting the country to its standing immediate-transmission baseline.</p>
<p>The change had a winding path to its effective date. Resolution NAC-DGERCGC25-00000014 (27 June 2025) deleted the ''or up to a maximum of four business days'' clause from Article 7, originally set to take effect 1 August 2025. But Resolution NAC-DGERCGC25-00000017 (29-30 July 2025) deferred that effective date to 1 January 2026, giving businesses roughly five extra months to adjust, while also shortening the invoice-cancellation window deadline from the 10th to the 7th of the following month and making ''consumidor final'' invoices non-cancellable outright.</p>
<p>Then, on 3 June 2026, the government issued Executive Decree 398, modernizing traceability and authentication mechanisms for goods and certain services. Press coverage from El Comercio frames the decree explicitly as building on the continuous, real-time invoice data stream SRI now receives -- since immediate transmission was restored -- to enable ongoing tax monitoring rather than the older model of reviewing data only after periodic declarations were filed. Read together, the two developments tell a coherent story: a mature, decade-old real-time invoicing infrastructure, briefly relaxed for a genuine crisis, restored, and now being actively built upon.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-08-05-ecuador-realtime-closure-and-decree398', 'es', 'Ecuador cierra su flexibilización de la era de emergencia en la facturación y luego construye sobre el flujo de datos que restableció', 'Ecuador cerró su flexibilización temporal de emergencia eléctrica en la facturación el 1 de enero de 2026, restableciendo la regla de transmisión inmediata vigente desde 2014 -- y en junio de 2026, el Decreto Ejecutivo 398 se apoyó en ese flujo continuo de datos para modernizar la trazabilidad de bienes y servicios.', '<h3>🇪🇨 Ecuador cierra su flexibilización de la era de emergencia en la facturación y luego construye sobre el flujo de datos que restableció</h3>
<p>Conviene ser precisos sobre qué cambió en el régimen de facturación electrónica de Ecuador el 1 de enero de 2026 -- porque es fácil caracterizarlo mal. No se trató de la introducción del reporte de facturas en tiempo real. El SRI de Ecuador exige la transmisión casi en tiempo real desde la Resolución NAC-DGERCGC14-00790 de 2014, endurecida y flexibilizada en los márgenes varias veces desde entonces, más recientemente con la ventana de 72 horas para alto volumen añadida en 2018. Lo que realmente ocurrió el 1 de enero de 2026 es que se eliminó el período de gracia temporal de 4 días hábiles concedido en noviembre de 2024, durante la emergencia eléctrica nacional y la crisis de apagones de Ecuador -- devolviendo al país a su regla base vigente de transmisión inmediata.</p>
<p>El cambio tuvo un camino sinuoso hasta su fecha de vigencia. La Resolución NAC-DGERCGC25-00000014 (27 de junio de 2025) eliminó del Artículo 7 la frase ''o hasta dentro de un máximo de cuatro días hábiles de haberse generado el mismo'', que originalmente debía entrar en vigor el 1 de agosto de 2025. Pero la Resolución NAC-DGERCGC25-00000017 (29-30 de julio de 2025) postergó esa fecha de vigencia al 1 de enero de 2026, dando a las empresas unos cinco meses adicionales para adaptarse, además de acortar el plazo de la ventana de anulación de facturas del día 10 al día 7 del mes siguiente y hacer directamente no anulables las facturas a ''consumidor final''.</p>
<p>Después, el 3 de junio de 2026, el gobierno emitió el Decreto Ejecutivo 398, que moderniza los mecanismos de trazabilidad y autenticación para bienes y determinados servicios. La cobertura de prensa de El Comercio enmarca el decreto explícitamente como una construcción sobre el flujo continuo y en tiempo real de datos de facturación que ahora recibe el SRI -- desde que se restableció la transmisión inmediata -- para habilitar un seguimiento tributario continuo, en lugar del antiguo modelo de revisar los datos solo tras la presentación de declaraciones periódicas. Leídos en conjunto, los dos desarrollos cuentan una historia coherente: una infraestructura de facturación en tiempo real madura, de una década de antigüedad, brevemente flexibilizada por una crisis genuina, restablecida, y ahora siendo activamente ampliada.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-08-05-ecuador-realtime-closure-and-decree398', 'de', 'Ecuador beendet seine Lockerung aus der Notstandszeit bei der Rechnungsstellung und baut dann auf dem wiederhergestellten Datenstrom auf', 'Ecuador beendete am 1. Januar 2026 seine vorübergehende Lockerung der Rechnungsstellung aus dem Stromnotstand und stellte damit die seit 2014 geltende Regel der sofortigen Übermittlung wieder her -- und im Juni 2026 baute das Exekutivdekret 398 auf diesem kontinuierlichen Datenstrom auf, um die Rückverfolgbarkeit von Waren und Dienstleistungen zu modernisieren.', '<h3>🇪🇨 Ecuador beendet seine Lockerung aus der Notstandszeit bei der Rechnungsstellung und baut dann auf dem wiederhergestellten Datenstrom auf</h3>
<p>Es lohnt sich, genau zu sein, was sich in Ecuadors E-Rechnungsregime am 1. Januar 2026 geändert hat -- denn es lässt sich leicht falsch darstellen. Dies war nicht die Einführung der Echtzeit-Rechnungsmeldung. Ecuadors SRI verlangt eine Echtzeit-nahe Übermittlung bereits seit der Entschließung NAC-DGERCGC14-00790 von 2014, seither mehrfach am Rand verschärft und gelockert, zuletzt durch die 2018 eingeführte 72-Stunden-Frist für hohes Volumen. Was am 1. Januar 2026 tatsächlich geschah, ist, dass die im November 2024 während Ecuadors nationalem Stromnotstand und der Blackout-Krise gewährte vorübergehende Karenzfrist von 4 Werktagen gestrichen wurde -- wodurch das Land zu seiner geltenden Basisregel der sofortigen Übermittlung zurückkehrte.</p>
<p>Die Änderung nahm einen verschlungenen Weg bis zu ihrem Inkrafttreten. Die Entschließung NAC-DGERCGC25-00000014 (27. Juni 2025) strich den Satz „oder innerhalb einer Frist von höchstens vier Werktagen nach dessen Erstellung" aus Artikel 7, ursprünglich vorgesehen zum Inkrafttreten am 1. August 2025. Doch die Entschließung NAC-DGERCGC25-00000017 (29./30. Juli 2025) verschob dieses Inkrafttreten auf den 1. Januar 2026 und gab Unternehmen damit rund fünf zusätzliche Monate zur Anpassung, während sie zugleich die Frist des Rechnungsstornierungsfensters vom 10. auf den 7. des Folgemonats verkürzte und Rechnungen an „consumidor final" gänzlich unwiderruflich machte.</p>
<p>Am 3. Juni 2026 erließ die Regierung dann das Exekutivdekret 398, das Rückverfolgbarkeits- und Authentifizierungsmechanismen für Waren und bestimmte Dienstleistungen modernisiert. Die Presseberichterstattung von El Comercio stellt das Dekret ausdrücklich als Weiterentwicklung des kontinuierlichen Echtzeit-Rechnungsdatenstroms dar, den das SRI nun erhält -- seit die sofortige Übermittlung wiederhergestellt wurde --, um eine fortlaufende Steuerüberwachung zu ermöglichen, statt des älteren Modells, Daten erst nach Einreichung periodischer Erklärungen zu prüfen. Zusammen gelesen erzählen die beiden Entwicklungen eine stimmige Geschichte: eine ausgereifte, jahrzehntealte Echtzeit-Rechnungsinfrastruktur, kurzzeitig für eine echte Krise gelockert, wiederhergestellt und nun aktiv weiterentwickelt.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-08-05-ecuador-realtime-closure-and-decree398', 'fr', 'L''Équateur met fin à son assouplissement de la facturation lié à l''urgence, puis s''appuie sur le flux de données rétabli', 'L''Équateur a mis fin à son assouplissement temporaire de la facturation lié à l''urgence électrique le 1er janvier 2026, rétablissant la règle de transmission immédiate en vigueur depuis 2014 -- et en juin 2026, le décret exécutif 398 s''est appuyé sur ce flux de données continu pour moderniser la traçabilité des biens et services.', '<h3>🇪🇨 L''Équateur met fin à son assouplissement de la facturation lié à l''urgence, puis s''appuie sur le flux de données rétabli</h3>
<p>Il convient d''être précis sur ce qui a changé dans le régime de facturation électronique de l''Équateur le 1er janvier 2026 -- car il est facile de le caractériser à tort. Il ne s''agissait pas de l''introduction de la déclaration des factures en temps réel. Le SRI équatorien exige une transmission quasi en temps réel depuis la résolution NAC-DGERCGC14-00790 de 2014, durcie et assouplie à la marge à plusieurs reprises depuis, la plus récente étant le délai de 72 heures pour fort volume ajouté en 2018. Ce qui s''est réellement passé le 1er janvier 2026, c''est que le délai de grâce temporaire de 4 jours ouvrables accordé en novembre 2024, pendant l''urgence électrique nationale et la crise des coupures de courant en Équateur, a été supprimé -- ramenant le pays à sa règle de base en vigueur de transmission immédiate.</p>
<p>Le changement a suivi un chemin sinueux jusqu''à sa date d''entrée en vigueur. La résolution NAC-DGERCGC25-00000014 (27 juin 2025) a supprimé de l''article 7 la clause « ou dans un délai maximal de quatre jours ouvrables après sa génération », dont l''entrée en vigueur était initialement prévue le 1er août 2025. Mais la résolution NAC-DGERCGC25-00000017 (29-30 juillet 2025) a reporté cette date d''entrée en vigueur au 1er janvier 2026, accordant aux entreprises environ cinq mois supplémentaires pour s''adapter, tout en raccourcissant également l''échéance de la fenêtre d''annulation des factures du 10 au 7 du mois suivant et en rendant les factures « consumidor final » purement et simplement non annulables.</p>
<p>Puis, le 3 juin 2026, le gouvernement a émis le décret exécutif 398, modernisant les mécanismes de traçabilité et d''authentification pour les biens et certains services. La presse d''El Comercio présente explicitement ce décret comme s''appuyant sur le flux continu de données de facturation en temps réel que le SRI reçoit désormais -- depuis le rétablissement de la transmission immédiate -- pour permettre un suivi fiscal continu, plutôt que l''ancien modèle consistant à n''examiner les données qu''après le dépôt des déclarations périodiques. Pris ensemble, ces deux développements racontent une histoire cohérente : une infrastructure de facturation en temps réel mature, vieille d''une décennie, brièvement assouplie pour une crise réelle, rétablie, et désormais activement développée.</p>');
